@app.cell
def _(auth_info, torch, mo):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    # Native architecture is shared with the bundled package: one maintained implementation.
    NativeTinyModel = (
        __import__("importlib").import_module("bifocalgemma.models.native").NativeTinyModel
    )
    configure_memory_efficient_training = (
        __import__("importlib")
        .import_module("bifocalgemma.models.memory_efficient")
        .configure_memory_efficient_training
    )
    run_training_memory_preflight = (
        __import__("importlib")
        .import_module("bifocalgemma.models.memory_efficient")
        .run_training_memory_preflight
    )
    TrainingDashboard = (
        __import__("importlib").import_module("bifocalgemma.training.telemetry").TrainingDashboard
    )
    resource_snapshot = (
        __import__("importlib").import_module("bifocalgemma.training.telemetry").resource_snapshot
    )

    ArchitectureModel = NativeTinyModel

    def build_model(spec, device, dtype, *, tiny=True):
        previous_dtype = torch.get_default_dtype()
        try:
            torch.set_default_dtype(dtype)
            with torch.device(device):
                return ArchitectureModel(spec, tiny=tiny)
        finally:
            torch.set_default_dtype(previous_dtype)

    mo.md(
        "## 6 · Model builder\nEncoder base + decoder IT; tying simetris, alignment asimetris, PLE terpisah. Optimasi memori tidak mengubah dimensi."
    )
    return (
        ArchitectureModel,
        build_model,
        configure_memory_efficient_training,
        run_training_memory_preflight,
        TrainingDashboard,
        resource_snapshot,
    )


@app.cell
def _(
    auth_info,
    Path,
    build_model,
    experiment_spec,
    gc,
    hashlib,
    hf_download_token,
    hf_hub_download,
    json,
    nn,
    re,
    safe_open,
    torch,
    F,
    mo,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    # 7. CHECKPOINT LOADER — original base/IT text weights, shared aliases.
    CHECKPOINTS = {
        "E2B": {
            "encoder": {
                "model_id": "google/gemma-4-E2B",
                "revision": "d29ff6b45f081a49ee2733a859c9c9c2d95d1a6f",
                "files": {
                    "tokenizer.json": "12bac982b793c44b03d52a250a9f0d0b666813da566b910c24a6da0695fd11e6",
                    "tokenizer_config.json": "12754e3442e47c1a1c55d550b617fc47ae227e8156ed1b1de0d8428195768b5c",
                    "config.json": "e5faef0dd1a8f2437f6010721146b85433eaa90e679ef011e803c7ffefae73b8",
                    "generation_config.json": "de16fa1d777387d5fe6df54a9565d9c0f1213f7b31f2a2cf44805e27686d9c7c",
                    "processor_config.json": "32bdf45d2ad4cc29a0822ddd157a182de76644f0419a6228d151495256e9813c",
                },
            },
            "decoder": {
                "model_id": "google/gemma-4-E2B-it",
                "revision": "3e22461f65e89153144f8adb70e3b8c2cc9845a7",
                "files": {
                    "tokenizer.json": "cc8d3a0ce36466ccc1278bf987df5f71db1719b9ca6b4118264f45cb627bfe0f",
                    "tokenizer_config.json": "9f4fec4b1dc6ecddf8f4a92e9caea5971c0e67d81309f3f9066a2bee8c362633",
                    "chat_template.jinja": "0a2c8073c878ab1da004bee933a998606537bbb62016310352c7285c3f01c5b5",
                    "config.json": "1b28f3d2c3100f6c594754b81107428bd7b822a7f48272ca681dae9d2ec38330",
                    "generation_config.json": "d4226bbe3117d2d253ba4609720ba82c6c4ce4627a9a6ae05387c78983ac03de",
                    "processor_config.json": "32bdf45d2ad4cc29a0822ddd157a182de76644f0419a6228d151495256e9813c",
                },
            },
        },
        "E4B": {
            "encoder": {
                "model_id": "google/gemma-4-E4B",
                "revision": "411aa17b749aa952df1359d2dcea73917a544d9a",
                "files": {
                    "tokenizer.json": "12bac982b793c44b03d52a250a9f0d0b666813da566b910c24a6da0695fd11e6",
                    "tokenizer_config.json": "6a9383197f000d2723684efd2210f5bf217bc29fa2cf360ae1574201b47af060",
                    "config.json": "f27a045f32c39fb9cd930204920de6b0962810cf09929a8810901ffaec780f20",
                    "generation_config.json": "de16fa1d777387d5fe6df54a9565d9c0f1213f7b31f2a2cf44805e27686d9c7c",
                    "processor_config.json": "32bdf45d2ad4cc29a0822ddd157a182de76644f0419a6228d151495256e9813c",
                },
            },
            "decoder": {
                "model_id": "google/gemma-4-E4B-it",
                "revision": "ee0ef6023621cff504d758262d4e04895a5af4a2",
                "files": {
                    "tokenizer.json": "cc8d3a0ce36466ccc1278bf987df5f71db1719b9ca6b4118264f45cb627bfe0f",
                    "tokenizer_config.json": "9f4fec4b1dc6ecddf8f4a92e9caea5971c0e67d81309f3f9066a2bee8c362633",
                    "chat_template.jinja": "0a2c8073c878ab1da004bee933a998606537bbb62016310352c7285c3f01c5b5",
                    "config.json": "33b10c02df3c2e8536cf323d29d53262aaa2f4d11dbe19bc729373fbe90295d4",
                    "generation_config.json": "d4226bbe3117d2d253ba4609720ba82c6c4ce4627a9a6ae05387c78983ac03de",
                    "processor_config.json": "32bdf45d2ad4cc29a0822ddd157a182de76644f0419a6228d151495256e9813c",
                },
            },
        },
    }

    def transfer_text_checkpoint(backbone, path: Path, *, skip_words: bool = False) -> dict:
        prefix = "model.language_model."
        target = backbone.state_dict()
        expected = {
            key: value
            for key, value in target.items()
            if not (skip_words and key == "embed_tokens.weight")
        }
        with safe_open(str(path), framework="pt", device="cpu") as reader:
            available = set(reader.keys())
            missing = [prefix + key for key in expected if prefix + key not in available]
            if missing:
                raise ValueError(f"Missing checkpoint tensors: {missing[:5]}")
            for key, value in expected.items():
                shape = reader.get_slice(prefix + key).get_shape()
                if tuple(shape) != tuple(value.shape):
                    raise ValueError(
                        f"Shape mismatch for {key}: source {shape}, target {tuple(value.shape)}"
                    )
            if any(value.is_meta for value in expected.values()):
                raise ValueError("Initialize destination storage before checkpoint transfer.")
            ignored_shared = []
            skipped = {prefix + "embed_tokens.weight"} if skip_words else set()
            for source_key in available:
                if not source_key.startswith(prefix) or source_key in skipped:
                    continue
                key = source_key[len(prefix) :]
                if key in expected:
                    continue
                match = re.fullmatch(
                    r"layers\.(\d+)\.self_attn\.(k_proj|v_proj|k_norm|v_norm)\.weight", key
                )
                layers = getattr(backbone, "layers", ())
                if (
                    match
                    and int(match[1]) < len(layers)
                    and layers[int(match[1])].self_attn.is_kv_shared_layer
                ):
                    ignored_shared.append(key)
                else:
                    raise ValueError(f"Unmapped text tensor: {key}")
            with torch.no_grad():
                for key, destination in expected.items():
                    source = reader.get_tensor(prefix + key)
                    # Direct CPU-mmap -> destination copy avoids a second large GPU PLE tensor.
                    destination.copy_(source)
        return {
            "text_prefix": prefix,
            "tensors_copied": len(expected),
            "encoder_words_skipped": skip_words,
            "ignored_shared_kv_tensors": sorted(ignored_shared),
            "nontext_tensors_ignored": sum(not key.startswith(prefix) for key in available),
        }

    class ProbeLoRALinear(nn.Module):
        def __init__(self, base: nn.Linear, rank: int = 16):
            super().__init__()
            if rank <= 0:
                raise ValueError("LoRA rank must be positive.")
            self.base = base
            self.base.requires_grad_(False)
            self.rank = rank
            self.scaling = 2.0  # alpha = 2 * rank
            self.lora_A = nn.Parameter(
                torch.empty(rank, base.in_features, device=base.weight.device, dtype=torch.float32)
            )
            self.lora_B = nn.Parameter(
                torch.zeros(base.out_features, rank, device=base.weight.device, dtype=torch.float32)
            )
            nn.init.normal_(self.lora_A, std=0.02)

        def forward(self, values):
            delta = F.linear(F.linear(values.float(), self.lora_A), self.lora_B)
            return self.base(values) + delta.to(values.dtype) * self.scaling

    def configure_probe_training(model, *, policy: str = "lora", rank: int = 16) -> dict:
        if policy not in {"lora", "full"}:
            raise ValueError("Training policy must be lora or full.")
        model.requires_grad_(policy == "full")
        adapted = []
        if policy == "lora":
            for name, module in list(model.named_modules()):
                if isinstance(module, nn.Linear) and name.rsplit(".", 1)[-1] in {
                    "q_proj",
                    "k_proj",
                    "v_proj",
                    "o_proj",
                }:
                    parent_name, attribute = name.rsplit(".", 1)
                    setattr(
                        model.get_submodule(parent_name), attribute, ProbeLoRALinear(module, rank)
                    )
                    adapted.append(name)
            # Asymmetric alignment is new, so it must remain trainable too.
            projection = getattr(model, "encoder_projection", None)
            if isinstance(projection, nn.Linear):
                projection.requires_grad_(True)
        trainable = [parameter for parameter in model.parameters() if parameter.requires_grad]
        if not trainable:
            raise ValueError("No trainable parameters were selected.")
        return {
            "policy": policy,
            "rank": rank if policy == "lora" else None,
            "adapter_modules": adapted,
            "trainable_parameters": sum(parameter.numel() for parameter in trainable),
            "trainable_bytes": tensor_bytes(trainable),
        }

    def tensor_bytes(tensors) -> int:
        seen = set()
        total = 0
        for tensor in tensors:
            # Parameters are unique across the iterator; object identity also dedups optimizer aliases.
            if id(tensor) not in seen:
                seen.add(id(tensor))
                total += tensor.numel() * tensor.element_size()
        return total

    def gpu_memory(device) -> dict:
        if torch.device(device).type != "cuda":
            return dict(
                allocated_bytes=None,
                reserved_bytes=None,
                free_bytes=None,
                total_bytes=None,
                peak_allocated_bytes=None,
                peak_reserved_bytes=None,
            )
        free, total = torch.cuda.mem_get_info(device)
        return dict(
            allocated_bytes=torch.cuda.memory_allocated(device),
            reserved_bytes=torch.cuda.memory_reserved(device),
            free_bytes=free,
            total_bytes=total,
            peak_allocated_bytes=torch.cuda.max_memory_allocated(device),
            peak_reserved_bytes=torch.cuda.max_memory_reserved(device),
        )

    def probe_estimate(spec, policy, rank, headroom_gib):
        with torch.device("meta"):
            blueprint = build_model(spec, "meta", torch.bfloat16, tiny=False)
        scope = configure_probe_training(blueprint, policy=policy, rank=rank)
        weights = tensor_bytes(blueprint.parameters())
        trainable = tensor_bytes(p for p in blueprint.parameters() if p.requires_grad)
        return {
            "weight_bytes": weights,
            "trainable_bytes": trainable,
            "estimated_gradient_and_adam_bytes": trainable * 3,
            "guard_bytes": weights + trainable * 3 + int(headroom_gib * 2**30),
            "trainable_parameters": scope["trainable_parameters"],
        }

    def gpu_guard(estimate, device):
        if device != "cuda":
            return "CUDA is required; no checkpoint downloaded."
        if not torch.cuda.is_bf16_supported():
            return "BF16 CUDA support is required; no checkpoint downloaded."
        free, total = torch.cuda.mem_get_info()
        if free < estimate["guard_bytes"]:
            return f"Free VRAM {free / 2**30:.2f} GiB < guard {estimate['guard_bytes'] / 2**30:.2f} GiB."
        return None

    def verified_assets(checkpoint, cache_dir):
        token = hf_download_token
        paths = {}
        for name, digest in checkpoint["files"].items():
            path = Path(
                hf_hub_download(
                    checkpoint["model_id"],
                    name,
                    revision=checkpoint["revision"],
                    cache_dir=cache_dir,
                    token=token,
                )
            )
            if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
                raise ValueError(f"Pinned asset hash mismatch: {checkpoint['model_id']}/{name}")
            paths[name] = path
        return paths

    def load_pretrained_probe(spec, cache_dir, seed, progress=None):
        torch.manual_seed(seed)
        decoder_ref = CHECKPOINTS[spec.decoder.size]["decoder"]
        encoder_ref = CHECKPOINTS[spec.encoder.size]["encoder"] if spec.encoder else None
        refs = [decoder_ref] + ([encoder_ref] if encoder_ref else [])
        source_files = []
        # Cache/config validation happens before destination GPU allocation.
        for ref in refs:
            if progress:
                progress({"stage": "checkpoint_download", "message": ref["model_id"]})
            assets = verified_assets(ref, cache_dir)
            print(f"Downloading/caching checkpoint {ref['model_id']} @ {ref['revision']} ...")
            weights = Path(
                hf_hub_download(
                    ref["model_id"],
                    "model.safetensors",
                    revision=ref["revision"],
                    cache_dir=cache_dir,
                    token=hf_download_token,
                )
            )
            source_files.append((ref, assets, weights))
        if progress:
            progress({"stage": "model_allocation", "message": spec.name})
        model = build_model(spec, "cuda", torch.bfloat16, tiny=False)
        if progress:
            progress({"stage": "checkpoint_transfer", "message": "decoder IT / encoder base"})
        mappings = []
        mappings.append(
            {
                "role": "decoder_it",
                "source": decoder_ref,
                **transfer_text_checkpoint(model.decoder, source_files[0][2]),
            }
        )
        if spec.encoder:
            assert model.encoder is not None
            mappings.append(
                {
                    "role": "encoder_base",
                    "source": encoder_ref,
                    **transfer_text_checkpoint(
                        model.encoder, source_files[1][2], skip_words=spec.tie_encoder_decoder_words
                    ),
                }
            )
        model._tie_words()
        return model, {
            "experiment": spec.name,
            "checkpoint_mapping": mappings,
            "encoder_words_anchor": "decoder_it"
            if spec.tie_encoder_decoder_words
            else "encoder_base",
            "PLE_shared": False,
            "new_alignment_projection": bool(spec.encoder and not spec.tie_encoder_decoder_words),
            "pretrained_weights_loaded": True,
            "checkpoint_format": "single_safetensors",
        }

    mo.md(
        "## 7 · Pretrained loading / LoRA\nSource revisions/keys/shapes tervalidasi; tying mengikuti spec."
    )
    return (
        CHECKPOINTS,
        ProbeLoRALinear,
        configure_probe_training,
        tensor_bytes,
        gpu_memory,
        probe_estimate,
        gpu_guard,
        verified_assets,
        load_pretrained_probe,
    )


@app.cell
def _(
    auth_info,
    EXPERIMENT,
    FAMILY,
    ProbeLoRALinear,
    build_model,
    configure_probe_training,
    copy,
    experiment_spec,
    math,
    nn,
    torch,
    mo,
    Any,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."

    # 7a. TRAINING POLICY — all family-specific training settings live here.
    class Float32Alignment(nn.Linear):
        """Keep small learned alignment in FP32 while returning backbone dtype."""

        def forward(self, input):
            return nn.functional.linear(input.float(), self.weight, self.bias).to(input.dtype)

    def default_training_profiles():
        common = {
            "version": "attention_lora_policy_v1",
            "rank": 16,
            "alpha": 32,
            "freeze_words": True,
            "freeze_ple": True,
            "phase": "joint",
        }
        profiles = {}
        for family in ("symmetric", "asymmetric"):
            groups = {name: {"lr": 2e-5, "warmup_steps": 5} for name in ("encoder", "decoder")}
            if family == "asymmetric":
                groups["alignment"] = {"lr": 2e-5, "warmup_steps": 5}
            profiles[family] = {
                **copy.deepcopy(common),
                "family": family,
                "train_alignment": family == "asymmetric",
                "groups": groups,
            }
        profiles["decoder_only"] = {
            **copy.deepcopy(common),
            "family": "decoder_only",
            "train_alignment": False,
            "groups": {"decoder": {"lr": 2e-5, "warmup_steps": 5}},
        }
        return profiles

    def validate_training_policy(policy, model=None):
        if "optimizer" in policy:
            validate_optimizer_config = (
                __import__("importlib")
                .import_module("bifocalgemma.training.optimizers")
                .validate_optimizer_config
            )

            validate_optimizer_config(policy["optimizer"])
        if type(policy.get("alignment_fp32", False)) is not bool:
            raise ValueError("alignment_fp32 must be boolean.")
        family = policy.get("family")
        if family not in {"symmetric", "asymmetric", "decoder_only"}:
            raise ValueError("Unknown training-policy family.")
        if policy.get("version") != "attention_lora_policy_v1" or policy.get("phase") != "joint":
            raise ValueError("Only joint attention LoRA policy v1 is supported.")
        if policy.get("freeze_words") is not True or policy.get("freeze_ple") is not True:
            raise ValueError("Word/PLE training needs a separately validated policy.")
        if type(policy.get("rank")) is not int or policy["rank"] < 1:
            raise ValueError("LoRA rank must be a positive integer.")
        if (
            not isinstance(policy.get("alpha"), (int, float))
            or not math.isfinite(policy["alpha"])
            or policy["alpha"] <= 0
        ):
            raise ValueError("LoRA alpha must be finite and positive.")
        expected = ({"decoder"} if family == "decoder_only" else {"encoder", "decoder"}) | (
            {"alignment"} if family == "asymmetric" else set()
        )
        if set(policy.get("groups", {})) != expected or policy.get("train_alignment") != (
            family == "asymmetric"
        ):
            raise ValueError("Policy groups/alignment do not match family.")
        for name, settings in policy["groups"].items():
            lr, warmup = settings.get("lr"), settings.get("warmup_steps")
            if not isinstance(lr, (int, float)) or not math.isfinite(lr) or lr <= 0:
                raise ValueError(f"Invalid LR for {name}.")
            if type(warmup) is not int or warmup < 0:
                raise ValueError(f"Invalid warmup for {name}.")
            if settings.get("scheduler", "constant") not in {"constant", "cosine"}:
                raise ValueError(f"Invalid scheduler for {name}.")
            for key in ("warmup_ratio", "min_lr_ratio"):
                value = settings.get(key, 0.0)
                if (
                    not isinstance(value, (int, float))
                    or not math.isfinite(value)
                    or not 0 <= value < 1
                ):
                    raise ValueError(f"Invalid {key} for {name}.")
        if model is not None:
            if family == "decoder_only":
                if model.encoder is not None or model.encoder_projection is not None:
                    raise ValueError("Decoder-only policy requires a baseline model.")
                return
            if getattr(model, "encoder", None) is None or model.spec.tie_encoder_decoder_words != (
                family == "symmetric"
            ):
                raise ValueError("Model architecture does not match policy family.")
            projection = model.encoder_projection
            if family == "symmetric" and not isinstance(projection, nn.Identity):
                raise ValueError("Symmetric policy expects Identity alignment.")
            if family == "asymmetric" and not isinstance(projection, nn.Linear):
                raise ValueError("Asymmetric policy expects a learned Linear alignment.")

    def configure_policy_model(model, policy):
        validate_training_policy(policy, model)
        scope = configure_probe_training(model, policy="lora", rank=policy["rank"])
        if policy.get("alignment_fp32") and isinstance(model.encoder_projection, nn.Linear):
            model.encoder_projection.__class__ = Float32Alignment
            model.encoder_projection.float()
        for module in model.modules():
            if isinstance(module, ProbeLoRALinear):
                module.scaling = policy["alpha"] / policy["rank"]
        scope["trainable_bytes"] = sum(
            p.numel() * p.element_size() for p in model.parameters() if p.requires_grad
        )
        return scope

    def build_training_groups(model, policy, total_steps=None) -> "list[dict[str, Any]]":
        validate_training_policy(policy, model)
        entries = {name: [] for name in ("encoder", "decoder", "alignment")}
        seen = set()
        # named_parameters deduplicates shared Parameter objects, including aliases.
        for name, parameter in sorted(model.named_parameters()):
            if not parameter.requires_grad:
                continue
            if id(parameter) in seen:
                raise ValueError("A trainable Parameter was enumerated twice.")
            seen.add(id(parameter))
            if name.startswith("encoder_projection.") and policy["train_alignment"]:
                group = "alignment"
            elif name.startswith("encoder.") and name.endswith((".lora_A", ".lora_B")):
                group = "encoder"
            elif name.startswith("decoder.") and name.endswith((".lora_A", ".lora_B")):
                group = "decoder"
            else:
                raise ValueError(
                    f"Unsupported trainable parameter: {name}; configure policy first."
                )
            entries[group].append((name, parameter))
        groups = []
        for name in ("encoder", "decoder", "alignment"):
            if name not in policy["groups"]:
                if entries[name]:
                    raise ValueError("Unexpected alignment parameters.")
                continue
            if not entries[name]:
                raise ValueError(f"Empty trainable group: {name}")
            settings = policy["groups"][name]
            schedule = {}
            if settings.get("scheduler", "constant") == "cosine":
                if total_steps is not None and (type(total_steps) is not int or total_steps < 1):
                    raise ValueError("Schedule horizon must be a positive integer.")
                schedule = {
                    "scheduler": "cosine",
                    "total_steps": total_steps,
                    "warmup_ratio": settings.get("warmup_ratio", 0.0),
                    "min_lr_ratio": settings.get("min_lr_ratio", 0.0),
                }
                if total_steps is not None:
                    schedule["warmup_steps"] = min(
                        total_steps,
                        max(
                            settings["warmup_steps"],
                            math.ceil(total_steps * schedule["warmup_ratio"]),
                        ),
                    )
            groups.append(
                {
                    "name": name,
                    "params": [p for _, p in entries[name]],
                    "param_names": [n for n, _ in entries[name]],
                    "lr": settings["lr"],
                    "base_lr": settings["lr"],
                    "warmup_steps": settings["warmup_steps"],
                    **schedule,
                }
            )
        if seen != {id(p) for p in model.parameters() if p.requires_grad}:
            raise ValueError("Optimizer groups do not cover all trainable parameters.")
        return groups

    def training_policy_table(groups, policy):
        return [
            {
                "group": group["name"],
                "base_lr": group["base_lr"],
                "warmup_steps": group["warmup_steps"],
                "scheduler": group.get("scheduler", "constant"),
                "warmup_ratio": group.get("warmup_ratio", 0.0),
                "min_lr_ratio": group.get("min_lr_ratio", 1.0),
                "parameters": sum(p.numel() for p in group["params"]),
                "dtypes": sorted({str(p.dtype) for p in group["params"]}),
                "words_frozen": policy["freeze_words"],
                "PLE_frozen": policy["freeze_ple"],
                "word_tying": "shared_IT_anchor" if policy["family"] == "symmetric" else "separate",
                "optimizer": policy.get("optimizer", {}).get("name", "adamw"),
                "alignment_fp32": policy.get("alignment_fp32", False),
            }
            for group in groups
        ]

    def optimizer_group_manifest(groups):
        return [
            {
                "name": group["name"],
                "param_names": list(group["param_names"]),
                "base_lr": group["base_lr"],
                "warmup_steps": group["warmup_steps"],
                **(
                    {
                        key: group[key]
                        for key in ("scheduler", "total_steps", "warmup_ratio", "min_lr_ratio")
                    }
                    if "scheduler" in group
                    else {}
                ),
            }
            for group in groups
        ]

    def update_policy_learning_rates(optimizer, step):
        if step < 0:
            raise ValueError("Optimizer step must be nonnegative.")
        rates = {}
        for group in optimizer.param_groups:
            warmup = group["warmup_steps"]
            fraction = min(1.0, (step + 1) / warmup) if warmup else 1.0
            if group.get("scheduler") == "cosine":
                total = group["total_steps"]
                if total is None:
                    raise ValueError("Cosine schedule needs a resolved training horizon.")
                if step + 1 > warmup:
                    # First post-warmup update starts decay; final update reaches the floor.
                    progress = min(1.0, (step + 1 - warmup) / max(1, total - warmup))
                    floor = group["min_lr_ratio"]
                    fraction = floor + (1 - floor) * 0.5 * (1 + math.cos(math.pi * progress))
            group["lr"] = group["base_lr"] * fraction
            rates[group["name"]] = group["lr"]
        return rates

    comparison_recipes = (
        __import__("importlib").import_module("bifocalgemma.training.recipes").comparison_recipes
    )
    # Single maintained numerical source, shared by all three notebooks.
    TRAINING_RECIPES = comparison_recipes(FAMILY)
    training_policy = copy.deepcopy(next(iter(TRAINING_RECIPES.values())))
    policy_spec = experiment_spec(EXPERIMENT)
    with torch.device("meta"):
        policy_blueprint = build_model(policy_spec, "meta", torch.bfloat16, tiny=False)
    configure_policy_model(policy_blueprint, training_policy)
    policy_table = [
        {"recipe": recipe, **row}
        for recipe, policy in TRAINING_RECIPES.items()
        for row in training_policy_table(build_training_groups(policy_blueprint, policy), policy)
    ]
    del policy_blueprint
    mo.vstack(
        [
            mo.md(
                "## 7a · Training policy\nDua recipe: base AdamW dan optimized Grokfast + OrScale-style LoRA. LR 2e-5, warm-up 3%, cosine → 10% untuk semua group/model. Rank16/alpha32, CE murni, word/PLE frozen. Angka dan optimizer ada di `comparison_recipes` (source bundle); TRAINING_RECIPES dapat diedit di cell ini. Tabel memakai blueprint meta; hasil optimized belum dijamin lebih baik."
            ),
            mo.ui.table(policy_table, selection=None),
            mo.ui.table(
                [
                    {"recipe": name, "optimizer_settings": str(policy["optimizer"])}
                    for name, policy in TRAINING_RECIPES.items()
                ],
                selection=None,
            ),
        ]
    )
    return (
        TRAINING_RECIPES,
        training_policy,
        policy_table,
        default_training_profiles,
        validate_training_policy,
        configure_policy_model,
        build_training_groups,
        training_policy_table,
        optimizer_group_manifest,
        update_policy_learning_rates,
    )


@app.cell
def _(
    auth_info,
    AutoTokenizer,
    CHECKPOINTS,
    Counter,
    Path,
    PurePosixPath,
    RepairCollator,
    TokenizedRepairExample,
    difflib,
    hashlib,
    hf_download_token,
    hf_hub_download,
    importlib,
    json,
    random,
    re,
    verified_assets,
    mo,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."

    # 8. DATA PREPARATION — target-free inputs; repair/localization/completion targets.
    def git_text_lines(text):
        """Git counts LF delimiters only; CR/formfeed/Unicode separators stay in content."""
        pieces = text.split("\n")
        return [line + "\n" for line in pieces[:-1]] + ([pieces[-1]] if pieces[-1] else [])

    def editing_record(raw: dict, *, source: str) -> dict:
        if raw.get("record_type") == "repository_patch_v1":
            return repository_editing_record(raw)
        before, after = raw.get("old_contents"), raw.get("new_contents")
        instruction = raw.get("instruction") if source == "editpackft" else raw.get("subject")
        if not isinstance(instruction, str) or not instruction.strip():
            raise ValueError("missing_instruction")
        if (
            not isinstance(before, str)
            or not isinstance(after, str)
            or not before
            or before == after
        ):
            raise ValueError("empty_or_unchanged_code")
        path = raw.get("old_file")
        if not isinstance(path, str) or raw.get("new_file") != path:
            raise ValueError("unsupported_rename_add_delete")
        canonical = PurePosixPath(path)
        if (
            canonical.is_absolute()
            or ".." in canonical.parts
            or "\\" in path
            or ":" in path
            or canonical.as_posix() != path
            or any(part.startswith(".") for part in canonical.parts)
            or any(char.isspace() for char in path)
        ):
            raise ValueError("unsupported_path")
        lines = list(
            difflib.unified_diff(
                git_text_lines(before),
                git_text_lines(after),
                fromfile=f"a/{path}",
                tofile=f"b/{path}",
                lineterm="\n",
            )
        )
        patch = f"diff --git a/{path} b/{path}\n"
        for line in lines:
            patch += line if line.endswith("\n") else line + "\n\\ No newline at end of file\n"
        pair_hash = hashlib.sha256((before + "\0" + after).encode("utf-8")).hexdigest()
        commit = str(raw.get("commit") or pair_hash)
        instruction_hash = hashlib.sha256(instruction.strip().encode("utf-8")).hexdigest()
        identifier = hashlib.sha256(
            (source + commit + path + pair_hash + instruction_hash).encode("utf-8")
        ).hexdigest()
        return {
            "instance_id": identifier,
            "group": commit,
            "pair_hash": pair_hash,
            "instruction_hash": instruction_hash,
            "path": path,
            "before": before,
            "after": after,
            "instruction": instruction.strip(),
            "target_patch": patch,
            "source": source,
            "commit": commit,
            "repos": str(raw.get("repos") or ""),
            "license": str(raw.get("license") or "unknown"),
        }

    def prepare_editing_records(raw_records, *, source, raw_limit=10000):
        if raw_limit < 2:
            raise ValueError("Need at least two raw records.")
        accepted, seen, filters = [], set(), Counter()
        for index, raw in enumerate(raw_records):
            if index >= raw_limit:
                break
            try:
                item = editing_record(raw, source=source)
            except ValueError as error:
                filters[str(error)] += 1
                continue
            if item["pair_hash"] in seen:
                filters["duplicate_before_after"] += 1
                continue
            seen.add(item["pair_hash"])
            accepted.append(item)
        return accepted, dict(filters)

    def split_editing_records(
        records, *, seed=17, dev_fraction=0.1, train_limit=2000, dev_limit=200
    ):
        if not 0 < dev_fraction < 1 or min(train_limit, dev_limit) < 1:
            raise ValueError("Invalid split/sample limits.")
        groups = sorted({record["group"] for record in records})
        if len(groups) < 2:
            raise ValueError("Need at least two distinct commit groups for a held-out split.")
        random.Random(seed).shuffle(groups)
        count = min(len(groups) - 1, max(1, round(len(groups) * dev_fraction)))
        dev_groups = set(groups[:count])
        train = [r for r in records if r["group"] not in dev_groups][:train_limit]
        dev = [r for r in records if r["group"] in dev_groups][:dev_limit]
        if not train or not dev:
            raise ValueError("Empty train/dev split.")
        assert not ({r["group"] for r in train} & {r["group"] for r in dev})
        return train, dev

    def editing_manifest(records):
        """Build run metadata from paired-file rows or native repository exports.

        Repository pools intentionally store snapshot/patch identity rather than the
        paired-file convenience hashes. Normalize a copy only; never rewrite frozen
        files, cohort IDs or split membership.
        """
        manifest = []
        for raw in records:
            row = raw
            if raw.get("record_type") == "context_sft_v1":
                normalize_context_task = (
                    __import__("importlib")
                    .import_module("bifocalgemma.data.context_tasks")
                    .normalize_context_task
                )

                row = normalize_context_task(raw)
            if raw.get("record_type") == "repository_patch_v1":
                row = repository_editing_record(raw)
                for key in ("pair_hash", "instruction_hash"):
                    if key in raw and raw[key] != row[key]:
                        raise ValueError("repository_manifest_hash_mismatch:" + key)
            manifest.append(
                {
                    **{
                        key: row[key]
                        for key in (
                            "record_type",
                            "source_revision",
                            "snapshot_sha256",
                            "context_selection",
                        )
                        if key in row
                    },
                    **{
                        key: row[key]
                        for key in (
                            "instance_id",
                            "group",
                            "pair_hash",
                            "instruction_hash",
                            "path",
                            "source",
                            "commit",
                            "repos",
                            "license",
                        )
                    },
                }
            )
        return manifest

    def stable_fingerprint(value):
        return hashlib.sha256(
            json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode(
                "utf-8"
            )
        ).hexdigest()

    def repository_editing_record(raw):
        """Consume only target-free-context training exports from the repo preparer."""
        if raw.get("role") != "train":
            raise ValueError("evaluation_record_cannot_enter_training")
        if raw.get("source", "").lower() in {
            "qurrent/res-q",
            "nuprl/canitedit",
            "bigcode/humanevalpack",
            "evalplus/repoqa",
        }:
            raise ValueError("benchmark_source_cannot_enter_training")
        instruction, context, patch = (
            raw.get("instruction"),
            raw.get("context"),
            raw.get("target_patch"),
        )
        if not all(isinstance(x, str) and x.strip() for x in (instruction, context, patch)):
            raise ValueError("missing_repository_training_fields")
        if raw.get("context_selection", {}).get("gold_used") is not False:
            raise ValueError("repository_context_policy_not_target_free")
        snapshot = raw.get("snapshot_sha256", "")
        if not re.fullmatch(r"[0-9a-f]{64}", snapshot):
            raise ValueError("missing_repository_snapshot_hash")
        for key in ("instance_id", "group", "commit", "repos", "source", "source_revision"):
            if not isinstance(raw.get(key), str) or not raw[key]:
                raise ValueError("missing_repository_provenance")
        if not patch.startswith("diff --git "):
            raise ValueError("unsupported_repository_target_patch")
        pair_hash = hashlib.sha256((snapshot + "\0" + patch).encode()).hexdigest()
        instruction_hash = hashlib.sha256(instruction.strip().encode()).hexdigest()
        return {
            **raw,
            "path": "repository_context",
            "before": context,
            "after": "",
            "pair_hash": pair_hash,
            "instruction_hash": instruction_hash,
            "license": str(raw.get("license") or "unknown"),
        }

    def curated_pool_digest(path):
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    def load_curated_pool(directory):
        """Honor a frozen full-pool split; verify every file and record before training."""
        from pathlib import Path

        root = Path(directory)
        manifest = json.loads((root / "manifest.json").read_text(encoding="utf-8"))
        if manifest.get("format") != "bifocalgemma_curated_pool_v1":
            raise ValueError("unsupported_curated_pool_format")
        fingerprint = manifest.get("fingerprint")
        if (
            stable_fingerprint({k: v for k, v in manifest.items() if k != "fingerprint"})
            != fingerprint
        ):
            raise ValueError("curated_pool_manifest_integrity")
        repository_pool = "snapshot_policy" in manifest.get("report", {})
        if (
            repository_pool
            and manifest["report"].get("context_source_license_policy")
            != "nearest_license_for_each_visible_file_v1"
        ):
            raise ValueError("repository_pool_context_license_audit_required")
        rows = {}
        all_ids = set()
        for split in ("train", "dev"):
            name = split + ".jsonl"
            if curated_pool_digest(root / name) != manifest["files"].get(name):
                raise ValueError("curated_pool_file_integrity:" + name)
            with (root / name).open(encoding="utf-8") as handle:
                items = [json.loads(line) for line in handle if line.strip()]
            if not items or [r["instance_id"] for r in items] != manifest["record_ids"][split]:
                raise ValueError("curated_pool_split_identity")
            for row in items:
                if row.get("pool_split") != split or row.get("role") != "train":
                    raise ValueError("curated_pool_role_or_split")
                if row["instance_id"] in all_ids:
                    raise ValueError("curated_pool_duplicate_identity")
                all_ids.add(row["instance_id"])
                if row.get("record_type") == "context_sft_v1":
                    normalize_context_task = (
                        __import__("importlib")
                        .import_module("bifocalgemma.data.context_tasks")
                        .normalize_context_task
                    )

                    normalize_context_task(row)
                    validate_context_license_record(row)
                elif row.get("record_type") == "repository_patch_v1":
                    repository_editing_record(row)
                    if repository_pool:
                        validate_context_license_record(row)
                elif not all(
                    isinstance(row.get(k), str) and row[k]
                    for k in (
                        "instruction",
                        "before",
                        "after",
                        "target_patch",
                        "source",
                        "source_revision",
                    )
                ):
                    raise ValueError("curated_pool_missing_fields")
            rows[split] = items
        return rows, manifest

    def validate_curated_pool_limits(manifest, *, encoder_limit, decoder_limit):
        """Reject control/manifest drift before training or loading model weights.

        Baselines must have room for the same context and paired target budget.
        Changing these controls requires a newly prepared, independently named pool.
        """
        if any(
            type(value) is not int or not 1 <= value <= 131072
            for value in (encoder_limit, decoder_limit)
        ):
            raise ValueError("Invalid requested pool token limits.")
        expected = {
            "encoder": encoder_limit,
            "pair_decoder": decoder_limit,
            "baseline_decoder": encoder_limit + decoder_limit + 512,
        }
        actual = manifest.get("report", {}).get("tokens", {}).get("limits")
        if actual != expected:
            raise ValueError(
                "Pool token limits differ: restore its limits or build a new named pool. "
                f"Requested {expected}; frozen {actual}."
            )
        return dict(actual)

    def validate_context_license_record(row):
        """Check complete recorded coverage; artifact hashes bind this provenance."""
        import importlib

        PERMITTED_CODE_LICENSES = importlib.import_module(
            "bifocalgemma.data.curation"
        ).PERMITTED_CODE_LICENSES

        paths = {window["path"] for window in row.get("context_selection", {}).get("windows", [])}
        evidence = row.get("context_source_code_license_evidence", [])
        recorded = [item["path"] for item in evidence]
        if not paths or set(recorded) != paths or len(set(recorded)) != len(recorded):
            raise ValueError("repository_context_license_coverage")
        for item in evidence:
            if not item.get("licenses"):
                raise ValueError("repository_context_license_missing")
            for license in item["licenses"]:
                if (
                    license.get("license") not in PERMITTED_CODE_LICENSES
                    or not isinstance(license.get("sha256"), str)
                    or not re.fullmatch(r"[0-9a-f]{64}", license.get("sha256", ""))
                ):
                    raise ValueError("repository_context_license_not_admitted")

    def tokenize_editing_row(row, spec, encoder, decoder, encoder_limit, decoder_limit):
        context = (
            row.get("context")
            or f"### Instruction\n{row['instruction']}\n\n### File: {row['path']}\n{row['before']}"
        )
        encoder_ids = tuple(encoder.encode(context, add_special_tokens=True))
        prefix = decoder.apply_chat_template(
            [
                {
                    "role": "user",
                    "content": "Return only a unified diff fulfilling the instruction.\n\n"
                    + row["instruction"],
                }
            ],
            tokenize=False,
            add_generation_prompt=True,
            enable_thinking=False,
        )
        messages = [
            {
                "role": "user",
                "content": "Return only a unified diff fulfilling the instruction.\n\n"
                + row["instruction"],
            },
            {"role": "assistant", "content": row["target_patch"]},
        ]
        complete = decoder.apply_chat_template(
            messages, tokenize=False, add_generation_prompt=False, enable_thinking=False
        )
        assert isinstance(prefix, str) and isinstance(complete, str)
        prefix_ids = tuple(decoder.encode(prefix, add_special_tokens=False))
        full_ids = tuple(decoder.encode(complete.rstrip(), add_special_tokens=False))
        if full_ids[: len(prefix_ids)] != prefix_ids:
            raise ValueError("prefix_boundary")
        target_ids = full_ids[len(prefix_ids) :]
        if encoder_ids[0] != 2 or prefix_ids[0] != 2 or not target_ids or target_ids[-1] != 106:
            raise ValueError("special_token_policy")
        if len(encoder_ids) > encoder_limit or len(full_ids) - 1 > decoder_limit:
            raise ValueError("token_overflow")
        return TokenizedRepairExample(
            row["instance_id"],
            encoder_ids,
            prefix_ids,
            target_ids,
            metadata={"source": row.get("source", "unknown")},
        )

    def prepare_training_data(
        spec, local_file, cache_dir, encoder_limit, decoder_limit, seed, progress=None
    ):
        if not 1 <= encoder_limit <= 131072 or not 1 <= decoder_limit <= 131072:
            raise ValueError("Invalid token limits.")
        source = "curated_pool"
        frozen_rows, pool_manifest = load_curated_pool(local_file)
        train_rows, dev_rows = frozen_rows["train"], frozen_rows["dev"]
        records = train_rows + dev_rows
        filters = {}
        assert spec.encoder is not None
        enc_ref = CHECKPOINTS[spec.encoder.size]["encoder"]
        dec_ref = CHECKPOINTS[spec.decoder.size]["decoder"]
        enc_assets = verified_assets(enc_ref, cache_dir)
        dec_assets = verified_assets(dec_ref, cache_dir)
        encoder = AutoTokenizer.from_pretrained(
            enc_assets["config.json"].parent, local_files_only=True, trust_remote_code=False
        )
        decoder = AutoTokenizer.from_pretrained(
            dec_assets["config.json"].parent, local_files_only=True, trust_remote_code=False
        )
        assert encoder is not None and decoder is not None
        token_filters = Counter()
        tokenized, kept = {}, {}
        for split, rows in (("train", train_rows), ("dev", dev_rows)):
            tokenized[split] = []
            kept[split] = []
            for index, row in enumerate(rows, 1):
                if progress and (index == 1 or index % 250 == 0 or index == len(rows)):
                    progress(
                        {
                            "stage": "tokenization",
                            "message": f"{split}: {index:,}/{len(rows):,}",
                            "data_split": split,
                            "items_done": index,
                            "items_total": len(rows),
                        }
                    )
                try:
                    item = tokenize_editing_row(
                        row, spec, encoder, decoder, encoder_limit, decoder_limit
                    )
                except ValueError as error:
                    raise ValueError(
                        "Frozen pool rejected by tokenizer; check its revision and token limits."
                    ) from error
                tokenized[split].append(item)
                kept[split].append(row)
        if not all(tokenized.values()):
            raise ValueError("Empty split after token filtering.")
        manifest = {
            "source": source,
            "source_ref": None,
            "split_policy": pool_manifest["report"]["split"]["policy"],
            "seed": seed,
            "encoder_limit": encoder_limit,
            "decoder_limit": decoder_limit,
            "tokenizer_sources": [enc_ref, dec_ref],
            "data_filters": filters,
            "token_filters": dict(token_filters),
            "train": editing_manifest(kept["train"]),
            "dev": editing_manifest(kept["dev"]),
        }
        if pool_manifest is not None:
            manifest["curated_pool_fingerprint"] = pool_manifest["fingerprint"]
            manifest["split_policy"] = pool_manifest["report"]["split"]["policy"]
            manifest["pool_report"] = pool_manifest["report"]
        manifest["data_format_version"] = (
            "repository_context_diff_v1"
            if all(r.get("record_type") == "repository_patch_v1" for r in records)
            else "paired_code_diff_v1"
        )
        manifest["tokenized_fingerprint"] = stable_fingerprint(
            {
                split: [
                    (item.instance_id, item.encoder_ids, item.decoder_prefix_ids, item.target_ids)
                    for item in items
                ]
                for split, items in tokenized.items()
            }
        )
        manifest["fingerprint"] = stable_fingerprint(manifest)
        return tokenized["train"], tokenized["dev"], manifest

    mo.md(
        "## 8 · Data / tokenisasi\nSeluruh train/dev dari koleksi HF beku; overflow ditolak dan split tidak diubah."
    )
    return (
        editing_record,
        prepare_editing_records,
        split_editing_records,
        editing_manifest,
        stable_fingerprint,
        prepare_training_data,
    )


@app.cell
def _(
    auth_info,
    RUN_TRAINING,
    RUN_BENCHMARKS,
    DATASET_REPO_ID,
    DATASET_REVISION,
    DATASET_COLLECTION,
    LOCAL_DATA_FILE,
    CORPUS_TOKENIZER_CACHE,
    CORPUS_KIND,
    ENCODER_LIMIT,
    DECODER_LIMIT,
    Path,
    importlib,
    corpus_assets_api,
    corpus_config_api,
    hf_download_token,
    mo,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    # Only a published immutable HF collection; every existing cache is verified.
    corpus_pool_status = {"status": "DISABLED", "path": LOCAL_DATA_FILE}
    if RUN_TRAINING or RUN_BENCHMARKS:
        _release_api = importlib.import_module("bifocalgemma.data.releases")
        with mo.status.spinner(title="Mengunduh / memverifikasi koleksi HF beku…"):
            _release_api.fetch_collection(
                DATASET_REPO_ID,
                DATASET_REVISION,
                DATASET_COLLECTION,
                LOCAL_DATA_FILE,
                token=hf_download_token,
            )
        _rows, _manifest = importlib.import_module(
            "bifocalgemma.data.offline_sft"
        ).load_curated_pool(LOCAL_DATA_FILE)
        _kind = (
            "multitask"
            if "task_counts" in _manifest["report"]
            else ("repository" if "snapshot_policy" in _manifest["report"] else "instruction")
        )
        if _kind != CORPUS_KIND:
            raise ValueError("Selected HF collection has another corpus kind.")
        _limits = importlib.import_module(
            "bifocalgemma.data.offline_sft"
        ).validate_curated_pool_limits(
            _manifest, encoder_limit=ENCODER_LIMIT, decoder_limit=DECODER_LIMIT
        )
        for _experiment in ("BifocalGemma-E2B-E2B", "BifocalGemma-E4B-E4B"):
            corpus_assets_api.fetch_tokenizer_assets(
                corpus_config_api.get_experiment(_experiment),
                Path(CORPUS_TOKENIZER_CACHE),
                token=hf_download_token,
            )
        corpus_pool_status = {
            "status": "READY",
            "syntax_diagnostics": _manifest["report"].get(
                "syntax_diagnostics_policy", "not_collected_in_this_frozen_pool"
            ),
            "limits": _limits,
            "path": LOCAL_DATA_FILE,
            "train": len(_manifest["record_ids"]["train"]),
            "dev": len(_manifest["record_ids"]["dev"]),
            "full_epoch_updates": _manifest["report"]["training_plan"]["updates_full_epoch"],
            "fingerprint": _manifest["fingerprint"],
        }
    mo.vstack(
        [
            mo.md(
                "## Frozen HF dataset\nDownload or verify the pinned collection, then train on all frozen train/dev IDs. Dataset curation is performed separately via the local CLI."
            ),
            mo.ui.table([corpus_pool_status], selection=None),
        ]
    )
    return (corpus_pool_status,)


@app.cell
def _(
    auth_info,
    Path,
    RepairCollator,
    build_training_groups,
    copy,
    hashlib,
    json,
    optimizer_group_manifest,
    random,
    safe_open,
    save_file,
    torch,
    update_policy_learning_rates,
    uuid4,
    mo,
    Any,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."

    # 9. TRAINING / CHECKPOINT — same helper code in both notebooks.
    def file_digest(path):
        digest = hashlib.sha256()
        with Path(path).open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    def cpu_tree(value):
        if isinstance(value, torch.Tensor):
            return value.detach().cpu()
        if isinstance(value, dict):
            return {key: cpu_tree(item) for key, item in value.items()}
        if isinstance(value, list):
            return [cpu_tree(item) for item in value]
        if isinstance(value, tuple):
            return tuple(cpu_tree(item) for item in value)
        return value

    def save_sft_checkpoint(
        model,
        optimizer,
        state,
        run_dir,
        compatibility,
        *,
        checkpoint_format="bifocalgemma_notebook_sft_v1",
    ):
        root = Path(run_dir).resolve()
        root.mkdir(parents=True, exist_ok=True)
        final = root / f"checkpoint-{state['global_step']:06d}"
        if final.exists():
            raise FileExistsError(f"Checkpoint exists; refusing overwrite: {final}")
        stage = root / (".partial-" + uuid4().hex)
        stage.mkdir()
        parameters = {
            name: p.detach().cpu().contiguous()
            for name, p in model.named_parameters()
            if p.requires_grad
        }
        if not all(bool(torch.isfinite(value).all()) for value in parameters.values()):
            raise ValueError("Refusing to save nonfinite trainable parameters.")
        save_file(parameters, str(stage / "adapters.safetensors"))
        payload = {
            "optimizer": cpu_tree(optimizer.state_dict()),
            "training_state": state,
            "torch_rng": torch.get_rng_state(),
            "python_rng": random.getstate(),
            "cuda_rng": torch.cuda.get_rng_state_all() if torch.cuda.is_available() else [],
        }
        torch.save(payload, stage / "trainer_state.pt")
        metadata = {
            "format": checkpoint_format,
            "global_step": state["global_step"],
            "compatibility": compatibility,
            "trainable_names": sorted(parameters),
        }
        if checkpoint_format == "bifocalgemma_notebook_sft_v2":
            metadata["optimizer_groups"] = optimizer_group_manifest(optimizer.param_groups)
        (stage / "manifest.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        marker = {
            name: file_digest(stage / name)
            for name in ("adapters.safetensors", "trainer_state.pt", "manifest.json")
        }
        (stage / "READY.json").write_text(json.dumps(marker, indent=2), encoding="utf-8")
        if stage.resolve().parent != root or final.resolve().parent != root:
            raise ValueError("Checkpoint targets escaped run directory.")
        stage.rename(final)
        return str(final)

    def restore_sft_checkpoint(
        model,
        optimizer,
        checkpoint_dir,
        compatibility,
        dataset_size,
        *,
        checkpoint_format="bifocalgemma_notebook_sft_v1",
    ):
        root = Path(checkpoint_dir)
        marker = json.loads((root / "READY.json").read_text(encoding="utf-8"))
        required = {"adapters.safetensors", "trainer_state.pt", "manifest.json"}
        if set(marker) != required or any(
            file_digest(root / name) != marker[name] for name in required
        ):
            raise ValueError("Checkpoint is incomplete or checksum validation failed.")
        manifest = json.loads((root / "manifest.json").read_text(encoding="utf-8"))
        if manifest.get("format") != checkpoint_format:
            raise ValueError(
                "Checkpoint format mismatch: grouped policy requires v2; resume v1 with the previous notebook."
            )
        if manifest["compatibility"] != compatibility:
            raise ValueError("Checkpoint experiment/data/tokenizer/optimizer config mismatch.")
        if checkpoint_format == "bifocalgemma_notebook_sft_v2":
            if manifest.get("optimizer_groups") != optimizer_group_manifest(optimizer.param_groups):
                raise ValueError("Checkpoint optimizer group order/names/policy mismatch.")
        parameters = {name: p for name, p in model.named_parameters() if p.requires_grad}
        if sorted(parameters) != manifest["trainable_names"]:
            raise ValueError("Checkpoint trainable parameter names differ.")
        payload = torch.load(root / "trainer_state.pt", map_location="cpu", weights_only=True)
        if checkpoint_format == "bifocalgemma_notebook_sft_v2":
            saved_groups = payload["optimizer"]["param_groups"]
            if optimizer_group_manifest(saved_groups) != optimizer_group_manifest(
                optimizer.param_groups
            ):
                raise ValueError("Saved optimizer groups differ from current policy.")
            if any(
                len(saved["params"]) != len(current["params"])
                for saved, current in zip(saved_groups, optimizer.param_groups, strict=True)
            ):
                raise ValueError("Saved optimizer parameter counts differ.")
        state = payload["training_state"]
        order, cursor = state["order"], state["cursor"]
        if sorted(order) != list(range(dataset_size)) or not 0 <= cursor <= len(order):
            raise ValueError("Invalid checkpoint sampler order/cursor.")
        if state["global_step"] != manifest["global_step"]:
            raise ValueError("Checkpoint step mismatch.")
        with safe_open(str(root / "adapters.safetensors"), framework="pt", device="cpu") as reader:
            if set(reader.keys()) != set(parameters):
                raise ValueError("Checkpoint adapter keys differ.")
            for name, p in parameters.items():
                if tuple(reader.get_slice(name).get_shape()) != tuple(p.shape):
                    raise ValueError(f"Checkpoint shape mismatch: {name}")
            with torch.no_grad():
                for name, p in parameters.items():
                    p.copy_(reader.get_tensor(name))
        optimizer.load_state_dict(payload["optimizer"])
        torch.set_rng_state(payload["torch_rng"])
        random.setstate(payload["python_rng"])
        if payload["cuda_rng"]:
            if len(payload["cuda_rng"]) != torch.cuda.device_count():
                raise ValueError("Checkpoint CUDA device count differs.")
            torch.cuda.set_rng_state_all(payload["cuda_rng"])
        return state

    def validation_batches(examples, batch_size):
        """Keep source/task attribution exact without changing the evaluation cohort."""
        pending = []
        previous_key = None
        for item in examples:
            key = (item.metadata.get("source", "unknown"), item.metadata.get("task_type", "repair"))
            if pending and (len(pending) == batch_size or key != previous_key):
                yield pending
                pending = []
            pending.append(item)
            previous_key = key
        if pending:
            yield pending

    def evaluate_sft_loss(model, examples, *, batch_size, device, event_callback=None, step=0):
        previous = model.training
        model.eval()
        total, tokens, by_source, by_task = 0.0, 0, {}, {}
        if event_callback:
            event_callback(
                {
                    "stage": "validation_started",
                    "step": step,
                    "eval_examples_done": 0,
                    "eval_examples_total": len(examples),
                }
            )
        try:
            with torch.no_grad():
                done = 0
                for items in validation_batches(examples, batch_size):
                    batch = RepairCollator()(items).to(device)
                    # Save ID/length before execution so a failed validation batch is reproducible.
                    if event_callback:
                        event_callback(
                            {
                                "stage": "validation_batch",
                                "step": step,
                                "instance_ids": [x.instance_id for x in items],
                                "encoder_tokens": batch.encoder_input_ids.shape[1],
                                "decoder_tokens": batch.decoder_input_ids.shape[1],
                                "batch_target_tokens": int((batch.labels != -100).sum()),
                            }
                        )
                    output = (
                        model.forward_loss(batch)
                        if hasattr(model, "forward_loss")
                        else model(batch)
                    )
                    assert output.loss is not None
                    if not bool(torch.isfinite(output.loss)):
                        raise RuntimeError("Nonfinite held-out loss.")
                    count = int((batch.labels != -100).sum())
                    loss_sum = output.loss.detach().item() * count
                    total += loss_sum
                    tokens += count
                    sources = {x.metadata.get("source", "unknown") for x in items}
                    source = next(iter(sources)) if len(sources) == 1 else "mixed_batch"
                    entry = by_source.setdefault(
                        source, {"loss_sum": 0.0, "supervised_tokens": 0, "examples": 0}
                    )
                    entry["loss_sum"] += loss_sum
                    entry["supervised_tokens"] += count
                    entry["examples"] += len(items)
                    tasks = {x.metadata.get("task_type", "repair") for x in items}
                    task = next(iter(tasks)) if len(tasks) == 1 else "mixed_batch"
                    task_entry = by_task.setdefault(
                        task, {"loss_sum": 0.0, "supervised_tokens": 0, "examples": 0}
                    )
                    task_entry["loss_sum"] += loss_sum
                    task_entry["supervised_tokens"] += count
                    task_entry["examples"] += len(items)
                    del output, batch
                    done += len(items)
                    if event_callback and (
                        done == len(items) or done == len(examples) or done % (25 * batch_size) == 0
                    ):
                        event_callback(
                            {
                                "stage": "validation_progress",
                                "step": step,
                                "eval_examples_done": done,
                                "eval_examples_total": len(examples),
                                "eval_running_loss": total / tokens if tokens else None,
                                "eval_target_tokens": tokens,
                            }
                        )
        finally:
            model.train(previous)
        if not tokens:
            raise ValueError("Held-out split has no supervised tokens.")
        result = {
            "loss": total / tokens,
            "supervised_tokens": tokens,
            "examples": len(examples),
            "by_source": {
                name: {
                    "loss": v["loss_sum"] / v["supervised_tokens"],
                    "supervised_tokens": v["supervised_tokens"],
                    "examples": v["examples"],
                }
                for name, v in by_source.items()
                if v["supervised_tokens"]
            },
            "by_task_type": {
                name: {
                    "loss": v["loss_sum"] / v["supervised_tokens"],
                    "supervised_tokens": v["supervised_tokens"],
                    "examples": v["examples"],
                }
                for name, v in by_task.items()
                if v["supervised_tokens"]
            },
        }
        if event_callback:
            event_callback(
                {
                    "stage": "validation_complete",
                    "step": step,
                    "dev_loss": result["loss"],
                    "eval_examples_done": len(examples),
                    "eval_examples_total": len(examples),
                    "eval": result,
                }
            )
        return result

    def fit_offline_sft(
        model,
        train,
        dev,
        run_dir,
        compatibility,
        *,
        max_steps=100,
        epochs=1,
        batch_size=1,
        eval_batch_size=None,
        accumulation=4,
        learning_rate=2e-5,
        warmup_steps=5,
        clip_norm=1.0,
        eval_every=25,
        save_every=25,
        seed=17,
        resume_from=None,
        progress=None,
        data_manifest=None,
        training_policy=None,
        event_callback=None,
        save_total_limit=2,
        checkpoint_callback=None,
    ) -> "dict[str, Any]":
        import time
        import traceback

        retained_checkpoints = (
            __import__("importlib")
            .import_module("bifocalgemma.training.stages")
            .retained_checkpoints
        )
        TrainingDashboard = (
            __import__("importlib")
            .import_module("bifocalgemma.training.telemetry")
            .TrainingDashboard
        )
        append_event = (
            __import__("importlib").import_module("bifocalgemma.training.telemetry").append_event
        )
        resource_snapshot = (
            __import__("importlib")
            .import_module("bifocalgemma.training.telemetry")
            .resource_snapshot
        )

        segment_started = time.perf_counter()
        evaluation_seconds = checkpoint_seconds = 0.0
        if (
            min(max_steps, epochs, batch_size, accumulation, eval_every, save_every) < 1
            or learning_rate <= 0
        ):
            raise ValueError("Invalid training settings.")
        if not train or not dev or clip_norm <= 0 or warmup_steps < 0 or save_total_limit < 1:
            raise ValueError("Need nonempty train/dev and valid clipping/warmup.")
        eval_batch_size = batch_size if eval_batch_size is None else eval_batch_size
        if type(eval_batch_size) is not int or eval_batch_size < 1:
            raise ValueError("Validation batch size must be a positive integer.")
        root = Path(run_dir)
        if not resume_from and root.exists() and any(root.iterdir()):
            raise FileExistsError(
                "Run directory already contains artifacts; choose new RUN_NAME or RESUME_FROM."
            )
        root.mkdir(parents=True, exist_ok=True)
        parameters = [p for p in model.parameters() if p.requires_grad]
        if not parameters:
            raise ValueError("No trainable parameters.")
        if getattr(model, "memory_policy", None):
            compatibility = {**compatibility, "memory_policy": copy.deepcopy(model.memory_policy)}
        checkpoint_format = "bifocalgemma_notebook_sft_v1"
        horizon = min(
            max_steps,
            epochs * ((len(train) + batch_size * accumulation - 1) // (batch_size * accumulation)),
        )
        if training_policy is None:
            optimizer = torch.optim.AdamW(
                parameters, lr=learning_rate, weight_decay=0.0, foreach=False
            )
        else:
            build_policy_optimizer = (
                __import__("importlib")
                .import_module("bifocalgemma.training.optimizers")
                .build_policy_optimizer
            )

            groups = build_training_groups(model, training_policy, total_steps=horizon)
            optimizer = build_policy_optimizer(groups, training_policy)
            compatibility = {
                **compatibility,
                "training_policy": copy.deepcopy(training_policy),
                "optimizer_groups": optimizer_group_manifest(groups),
            }
            checkpoint_format = "bifocalgemma_notebook_sft_v2"
        device = next(model.parameters()).device
        order = list(range(len(train)))
        random.Random(seed).shuffle(order)
        state: dict = {"global_step": 0, "epoch": 0, "order": order, "cursor": 0, "history": []}
        # All resume validation precedes changes to run metadata or diagnostics.
        if resume_from:
            state = restore_sft_checkpoint(
                model,
                optimizer,
                resume_from,
                compatibility,
                len(train),
                checkpoint_format=checkpoint_format,
            )
        if data_manifest is not None:
            (root / "data_manifest.json").write_text(
                json.dumps(data_manifest, indent=2), encoding="utf-8"
            )
        (root / "run_config.json").write_text(json.dumps(compatibility, indent=2), encoding="utf-8")
        log_file = root / "history.jsonl"
        if resume_from:
            log_file.write_text(
                "".join(json.dumps(r) + "\n" for r in state["history"]), encoding="utf-8"
            )
        model.train()
        checkpoints = []
        last_checkpoint = str(resume_from) if resume_from else None
        last_checkpoint_step = state["global_step"] if resume_from else -1
        if device.type == "cuda":
            torch.cuda.reset_peak_memory_stats(device)
        latest_batch = {}
        phase = "run_started"
        if event_callback is None:
            event_callback = TrainingDashboard(None, device=device)

        def emit(event):
            nonlocal phase, latest_batch
            phase = event["stage"]
            if "instance_ids" in event:
                latest_batch = {
                    k: event[k]
                    for k in (
                        "instance_ids",
                        "encoder_tokens",
                        "decoder_tokens",
                        "batch_target_tokens",
                    )
                    if k in event
                }
            row = {
                "step": state["global_step"],
                "epoch_fraction": state["epoch"] + state["cursor"] / len(train),
                "max_steps": max_steps,
                "accumulation": accumulation,
                "elapsed_seconds": time.perf_counter() - segment_started,
                **event,
                **resource_snapshot(device),
            }
            payload = append_event(root / "events.jsonl", row)
            if event_callback:
                event_callback(payload)
            return payload

        old_callback = getattr(model, "_stage_callback", None)

        def model_stage(event):
            # Suppress per-stack validation events; validation counters remain visible.
            if model.training:
                emit(event)

        model._stage_callback = model_stage
        try:
            emit(
                {
                    "stage": "run_started",
                    "run_dir": str(root.resolve()),
                    "train_examples": len(train),
                    "dev_examples": len(dev),
                    "batch_size": batch_size,
                    "eval_batch_size": eval_batch_size,
                    "eval_every": eval_every,
                    "save_every": save_every,
                    "optimizer_name": (training_policy or {})
                    .get("optimizer", {})
                    .get("name", "adamw"),
                    "optimizer_groups": optimizer_group_manifest(optimizer.param_groups)
                    if training_policy is not None
                    else None,
                    "last_checkpoint": last_checkpoint,
                    "memory_policy": getattr(model, "memory_policy", None),
                    **getattr(model, "memory_policy", {}),
                    "history": state["history"],
                }
            )
            while state["global_step"] < max_steps and state["epoch"] < epochs:
                if state["cursor"] >= len(state["order"]):
                    state["epoch"] += 1
                    if state["epoch"] >= epochs:
                        break
                    state["order"] = list(range(len(train)))
                    random.Random(seed + state["epoch"]).shuffle(state["order"])
                    state["cursor"] = 0
                step_started = time.perf_counter()
                micro_batches, item_batches = [], []
                for micro in range(accumulation):
                    if state["cursor"] >= len(state["order"]):
                        break
                    indices = state["order"][state["cursor"] : state["cursor"] + batch_size]
                    state["cursor"] += len(indices)
                    items = [train[index] for index in indices]
                    item_batches.append(items)
                    micro_batches.append(RepairCollator()(items))
                token_count = sum(int((batch.labels != -100).sum()) for batch in micro_batches)
                if not token_count:
                    raise ValueError("No supervised tokens in optimizer window.")
                optimizer.zero_grad(set_to_none=True)
                mean_loss, window_sources, phase_times = (
                    0.0,
                    {},
                    {"forward_seconds": 0.0, "backward_seconds": 0.0},
                )
                window_tasks = {}
                for micro, (batch_cpu, items) in enumerate(
                    zip(micro_batches, item_batches, strict=True), 1
                ):
                    batch = batch_cpu.to(device)
                    count = int((batch_cpu.labels != -100).sum())
                    emit(
                        {
                            "stage": "microbatch_started",
                            "microbatch": micro,
                            "instance_ids": [x.instance_id for x in items],
                            "encoder_tokens": batch.encoder_input_ids.shape[1],
                            "decoder_tokens": batch.decoder_input_ids.shape[1],
                            "batch_target_tokens": count,
                            "optimizer_window_target_tokens": token_count,
                        }
                    )
                    phase_started = time.perf_counter()
                    emit({"stage": "forward_started"})
                    output = (
                        model.forward_loss(batch)
                        if hasattr(model, "forward_loss")
                        else model(batch)
                    )
                    assert output.loss is not None
                    if not bool(torch.isfinite(output.loss)):
                        raise RuntimeError("Nonfinite training loss.")
                    phase_times["forward_seconds"] += time.perf_counter() - phase_started
                    emit({"stage": "backward_started"})
                    phase_started = time.perf_counter()
                    (output.loss * (count / token_count)).backward()
                    if device.type == "cuda":
                        torch.cuda.synchronize(device)
                    phase_times["backward_seconds"] += time.perf_counter() - phase_started
                    batch_loss = output.loss.detach().item()
                    mean_loss += batch_loss * (count / token_count)
                    sources = {x.metadata.get("source", "unknown") for x in items}
                    source = next(iter(sources)) if len(sources) == 1 else "mixed_batch"
                    entry = window_sources.setdefault(
                        source, {"loss_sum": 0.0, "supervised_tokens": 0}
                    )
                    entry["loss_sum"] += batch_loss * count
                    entry["supervised_tokens"] += count
                    tasks = {x.metadata.get("task_type", "repair") for x in items}
                    task = next(iter(tasks)) if len(tasks) == 1 else "mixed_batch"
                    task_entry = window_tasks.setdefault(
                        task, {"loss_sum": 0.0, "supervised_tokens": 0}
                    )
                    task_entry["loss_sum"] += batch_loss * count
                    task_entry["supervised_tokens"] += count
                    del output, batch
                    emit({"stage": "microbatch_complete", "microbatch": micro})
                gradients = [p.grad for p in parameters if p.grad is not None]
                if not gradients or not all(bool(torch.isfinite(g).all()) for g in gradients):
                    raise RuntimeError("Missing/nonfinite training gradients.")
                norm = torch.nn.utils.clip_grad_norm_(parameters, clip_norm, foreach=False)
                if not bool(torch.isfinite(norm)):
                    raise RuntimeError("Nonfinite gradient norm.")
                fraction = (
                    min(1.0, (state["global_step"] + 1) / warmup_steps) if warmup_steps else 1.0
                )
                if training_policy is None:
                    for group in optimizer.param_groups:
                        group["lr"] = learning_rate * fraction
                    rates = {"default": learning_rate * fraction}
                else:
                    rates = update_policy_learning_rates(optimizer, state["global_step"])
                emit({"stage": "optimizer_started", "learning_rates": rates})
                optimizer_started = time.perf_counter()
                optimizer.step()
                optimizer.zero_grad(set_to_none=True)
                if device.type == "cuda":
                    torch.cuda.synchronize(device)
                phase_times["optimizer_seconds"] = time.perf_counter() - optimizer_started
                del gradients, micro_batches
                state["global_step"] += 1
                seconds = time.perf_counter() - step_started
                row = {
                    "step": state["global_step"],
                    "epoch": state["epoch"],
                    "epoch_fraction": state["epoch"] + state["cursor"] / len(train),
                    "train_loss": mean_loss,
                    "target_tokens": token_count,
                    "gradient_norm": norm.detach().item(),
                    "step_seconds": seconds,
                    **phase_times,
                    "target_tokens_per_second": token_count / seconds,
                    "by_source": {
                        name: {
                            "loss": v["loss_sum"] / v["supervised_tokens"],
                            "supervised_tokens": v["supervised_tokens"],
                        }
                        for name, v in window_sources.items()
                    },
                    "last_batch": latest_batch,
                    "by_task_type": {
                        name: {
                            "loss": v["loss_sum"] / v["supervised_tokens"],
                            "supervised_tokens": v["supervised_tokens"],
                        }
                        for name, v in window_tasks.items()
                    },
                    **resource_snapshot(device),
                }
                if training_policy is None:
                    row["learning_rate"] = rates["default"]
                else:
                    row["learning_rates"] = rates
                if hasattr(optimizer, "last_diagnostics"):
                    row["optimizer_diagnostics"] = copy.deepcopy(optimizer.last_diagnostics)
                if device.type == "cuda":
                    row["peak_allocated_gib"] = torch.cuda.max_memory_allocated(device) / 2**30
                recent_times = [r.get("step_seconds", seconds) for r in state["history"][-19:]] + [
                    seconds
                ]
                row["eta_train_seconds"] = (
                    sum(recent_times) / len(recent_times) * max(0, max_steps - state["global_step"])
                )
                emit({"stage": "optimizer_step_complete", **row, "learning_rates": rates})
                # Final CE is computed once below, including when the last step
                # happens to be a periodic validation boundary.
                if state["global_step"] % eval_every == 0 and state["global_step"] < horizon:
                    started = time.perf_counter()
                    row["eval"] = evaluate_sft_loss(
                        model,
                        dev,
                        batch_size=eval_batch_size,
                        device=device,
                        event_callback=emit,
                        step=state["global_step"],
                    )
                    row["eval_seconds"] = time.perf_counter() - started
                    evaluation_seconds += row["eval_seconds"]
                state["history"].append(row)
                with log_file.open("a", encoding="utf-8") as stream:
                    stream.write(json.dumps(row, allow_nan=False) + "\n")
                if progress:
                    progress(row)
                if state["global_step"] % save_every == 0:
                    started = time.perf_counter()
                    emit({"stage": "checkpoint_started"})
                    last_checkpoint = save_sft_checkpoint(
                        model,
                        optimizer,
                        state,
                        root,
                        compatibility,
                        checkpoint_format=checkpoint_format,
                    )
                    checkpoints = retained_checkpoints(root, limit=save_total_limit)
                    if checkpoint_callback:
                        checkpoint_callback(last_checkpoint)
                    checkpoint_seconds += time.perf_counter() - started
                    last_checkpoint_step = state["global_step"]
                    emit(
                        {
                            "stage": "checkpoint_complete",
                            "last_checkpoint": last_checkpoint,
                            "checkpoint_seconds": time.perf_counter() - started,
                        }
                    )
            started = time.perf_counter()
            evaluation = evaluate_sft_loss(
                model,
                dev,
                batch_size=eval_batch_size,
                device=device,
                event_callback=emit,
                step=state["global_step"],
            )
            evaluation_seconds += time.perf_counter() - started
            if state["global_step"] != last_checkpoint_step:
                started = time.perf_counter()
                emit({"stage": "checkpoint_started"})
                last_checkpoint = save_sft_checkpoint(
                    model,
                    optimizer,
                    state,
                    root,
                    compatibility,
                    checkpoint_format=checkpoint_format,
                )
                checkpoints = retained_checkpoints(root, limit=save_total_limit)
                if checkpoint_callback:
                    checkpoint_callback(last_checkpoint)
                checkpoint_seconds += time.perf_counter() - started
                emit(
                    {
                        "stage": "checkpoint_complete",
                        "last_checkpoint": last_checkpoint,
                        "checkpoint_seconds": time.perf_counter() - started,
                    }
                )
            checkpoints = retained_checkpoints(root, limit=save_total_limit)
            result = {
                "status": "COMPLETED",
                "global_step": state["global_step"],
                "epoch": state["epoch"],
                "history": state["history"],
                "held_out_eval": evaluation,
                "checkpoints": checkpoints,
                "resume_from": str(resume_from) if resume_from else None,
                "checkpoint_format": checkpoint_format,
                "memory_policy": getattr(model, "memory_policy", None),
                "training_policy": copy.deepcopy(training_policy),
                "cadence": {
                    "eval_every": eval_every,
                    "save_every": save_every,
                    "total_steps": horizon,
                },
                "last_checkpoint": last_checkpoint,
                "segment_seconds": time.perf_counter() - segment_started,
                "segment_evaluation_seconds": evaluation_seconds,
                "segment_checkpoint_seconds": checkpoint_seconds,
                "peak_allocated_bytes": torch.cuda.max_memory_allocated(device)
                if device.type == "cuda"
                else None,
                "peak_reserved_bytes": torch.cuda.max_memory_reserved(device)
                if device.type == "cuda"
                else None,
                "resources": resource_snapshot(device),
                "events_file": str(root / "events.jsonl"),
                "monitor_file": str(root / "monitor.html"),
            }
            result["timing"] = {
                "segment_wall_seconds": result["segment_seconds"],
                "segment_evaluation_seconds": evaluation_seconds,
                "segment_checkpoint_seconds": checkpoint_seconds,
            }
            result["functional_benchmark_run"] = False
            result["optimizer_groups"] = (
                optimizer_group_manifest(optimizer.param_groups)
                if training_policy is not None
                else None
            )
            (root / "training_report.json").write_text(
                json.dumps(result, indent=2), encoding="utf-8"
            )
            emit(
                {
                    "stage": "completed",
                    "dev_loss": evaluation["loss"],
                    "last_checkpoint": last_checkpoint,
                }
            )
            return result
        except BaseException as exc:
            failed_stage = phase
            failure = {
                "status": "INTERRUPTED" if isinstance(exc, KeyboardInterrupt) else "FAILED",
                "stage": failed_stage,
                "global_step": state["global_step"],
                "error_type": type(exc).__name__,
                "error": str(exc),
                "last_checkpoint": last_checkpoint,
                "last_batch": latest_batch,
                "traceback": traceback.format_exc(),
                "resources": resource_snapshot(device),
            }
            (root / "failure.json").write_text(json.dumps(failure, indent=2), encoding="utf-8")
            emit(
                {
                    "stage": "interrupted" if isinstance(exc, KeyboardInterrupt) else "failed",
                    "failed_stage": failed_stage,
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                    "last_checkpoint": last_checkpoint,
                    **latest_batch,
                }
            )
            model.zero_grad(set_to_none=True)
            optimizer.state.clear()
            traceback.clear_frames(exc.__traceback__)
            raise
        finally:
            model._stage_callback = old_callback

    mo.md(
        "## 9 · SFT / checkpoint\nToken-weighted gradient accumulation, clipping, dev CE, optimizer/RNG/cursor resume."
    )
    return (
        file_digest,
        cpu_tree,
        save_sft_checkpoint,
        restore_sft_checkpoint,
        evaluate_sft_loss,
        fit_offline_sft,
    )


@app.cell
def _(
    auth_info,
    EXPERIMENT,
    FAMILY,
    HEADROOM_GIB,
    training_policy,
    RUN_TRAINING,
    RUN_BENCHMARKS,
    device,
    experiment_spec,
    gpu_guard,
    probe_estimate,
    mo,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    # 10. PREFLIGHT — no data/model downloads here.
    training_spec = experiment_spec(EXPERIMENT)
    assert (training_spec.encoder is None) == (FAMILY == "decoder_only")
    assert training_spec.tie_encoder_decoder_words == (FAMILY == "symmetric")
    training_estimate = probe_estimate(training_spec, "lora", training_policy["rank"], HEADROOM_GIB)
    training_guard = (
        gpu_guard(training_estimate, device)
        if RUN_TRAINING or RUN_BENCHMARKS
        else "RUN_TRAINING=False and RUN_BENCHMARKS=False"
    )
    mo.vstack(
        [
            mo.md("## 10 · Preflight"),
            mo.ui.table(
                [
                    {
                        "family": FAMILY,
                        "model": EXPERIMENT,
                        "ready": training_guard is None,
                        "reason": training_guard,
                        "estimated_weights_gib": training_estimate["weight_bytes"] / 2**30,
                        "word_tying": training_spec.tie_encoder_decoder_words,
                        "alignment": "none"
                        if FAMILY == "decoder_only"
                        else ("identity" if FAMILY == "symmetric" else "learned"),
                    }
                ],
                selection=None,
            ),
        ]
    )
    return (
        training_spec,
        training_estimate,
        training_guard,
    )


@app.cell
def _(auth_info, LOCAL_DATA_FILE, corpus_pool_status, EXPERIMENT_SEQUENCE, TRAINING_RECIPES, mo):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    # Data plan only: tokenize inside the model loop, so arrays from an earlier model do not stay resident.
    sequence_data_plan = {
        "status": corpus_pool_status["status"],
        "collection_path": LOCAL_DATA_FILE,
        "sequence": [
            f"{model}/{recipe}" for model in EXPERIMENT_SEQUENCE for recipe in TRAINING_RECIPES
        ],
        "sampling": "all frozen train/dev IDs",
    }
    mo.vstack(
        [mo.md("## 11 · Sequential data plan"), mo.ui.table([sequence_data_plan], selection=None)]
    )
    return (sequence_data_plan,)


@app.cell
def _(
    AUTO_RESUME,
    BENCHMARK_CACHE,
    BENCHMARK_COLLECTIONS,
    BENCHMARK_UPLOAD_EVERY,
    BATCH_SIZE,
    EVAL_BATCH_SIZE,
    CACHE_DIR,
    CHECKPOINT_UPLOAD_ENABLED,
    CORPUS_TOKENIZER_CACHE,
    DATASET_COLLECTION,
    DATASET_REPO_ID,
    DATASET_REVISION,
    EPOCHS,
    EVAL_FRACTION,
    EXPERIMENT_SEQUENCE,
    FAMILY,
    FUNCTIONAL_BENCHMARKS,
    GRAD_ACCUMULATION,
    HEADROOM_GIB,
    HF_REPO_ID,
    HF_UPLOAD_ENABLED,
    LOCAL_DATA_FILE,
    MAX_GRAD_NORM,
    MAX_STEPS,
    MEMORY_POLICY,
    OUTPUT_ROOT,
    Path,
    RESUME_FROM,
    RUN_BENCHMARKS,
    RUN_NAME,
    RUN_TRAINING,
    CHECKPOINT_FRACTION,
    SAVE_TOTAL_LIMIT,
    SEED,
    TRAINING_RECIPES,
    auth_info,
    environment,
    gpu_guard,
    hf_download_token,
    load_pretrained_probe,
    mo,
    probe_estimate,
    sequence_data_plan,
    training_guard,
    training_policy,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    run_recipe_comparison = (
        __import__("importlib").import_module("bifocalgemma.training.recipes").run_recipe_comparison
    )
    training_result = {"status": "DISABLED", "reason": training_guard, "models": []}
    run_dir = Path(OUTPUT_ROOT)
    if training_guard is None:
        if SAVE_TOTAL_LIMIT != 2:
            raise ValueError(
                "This notebook preserves exactly the two latest checkpoints per model."
            )
        if HF_UPLOAD_ENABLED and auth_info.get("role") == "read":
            raise ValueError("Apply a write token before sequential training/upload.")
        if sequence_data_plan["status"] != "READY":
            raise ValueError("The pinned dataset must be READY before starting.")

        def model_factory(spec, progress):
            guard = gpu_guard(
                probe_estimate(spec, "lora", training_policy["rank"], HEADROOM_GIB),
                environment["device"],
            )
            if guard:
                raise RuntimeError(guard)
            return load_pretrained_probe(spec, CACHE_DIR, SEED, progress=progress)

        training_result = run_recipe_comparison(
            family=FAMILY,
            experiments=EXPERIMENT_SEQUENCE,
            output_root=OUTPUT_ROOT,
            run_name=RUN_NAME,
            dataset_repo=DATASET_REPO_ID,
            dataset_revision=DATASET_REVISION,
            collection=DATASET_COLLECTION,
            pool_directory=LOCAL_DATA_FILE,
            tokenizer_cache=CORPUS_TOKENIZER_CACHE,
            benchmark_collections=BENCHMARK_COLLECTIONS,
            benchmark_cache=BENCHMARK_CACHE,
            model_factory=model_factory,
            recipes=TRAINING_RECIPES,
            memory_policy=MEMORY_POLICY,
            environment=environment,
            model_repo=HF_REPO_ID,
            token=hf_download_token,
            mo=mo,
            epochs=EPOCHS,
            batch_size=BATCH_SIZE,
            eval_batch_size=EVAL_BATCH_SIZE,
            accumulation=GRAD_ACCUMULATION,
            max_steps=MAX_STEPS,
            eval_fraction=EVAL_FRACTION,
            save_fraction=CHECKPOINT_FRACTION,
            clip_norm=MAX_GRAD_NORM,
            seed=SEED,
            run_training=RUN_TRAINING,
            run_benchmarks=RUN_BENCHMARKS,
            upload=HF_UPLOAD_ENABLED,
            resume_from=RESUME_FROM or None,
            checkpoint_upload=CHECKPOINT_UPLOAD_ENABLED,
            benchmark_upload_every=BENCHMARK_UPLOAD_EVERY,
            functional_execution=FUNCTIONAL_BENCHMARKS,
            auto_resume=AUTO_RESUME,
            benchmark_reset_id="2026-10-17-clean-evaluation-v1",
        )
    else:
        mo.output.replace(mo.md("Pipeline disabled / preflight blocked: " + str(training_guard)))
    return (training_result, run_dir)


@app.cell
def _(auth_info, mo, run_dir, training_result):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    result_summary = [
        {
            "experiment": row["experiment"],
            "recipe": row["recipe"],
            "status": row["status"],
            "optimizer_steps": row["global_step"],
            "dev_loss": row["held_out_eval"]["loss"],
            "benchmark_stages": sum(k.startswith("benchmark:") for k in row["stages"]),
            "backup_status": row.get("benchmark_backup", {}).get("status", "NOT_STARTED"),
            "run_dir": row["run_dir"],
        }
        for row in training_result.get("models", [])
    ]
    mo.vstack(
        [
            mo.md(f"## 13 · Sequential results\nArtifacts: `{run_dir}`"),
            mo.ui.table(result_summary or [{"status": training_result["status"]}], selection=None),
        ]
    )
    return (result_summary,)


@app.cell
def _(auth_info, HF_REPO_ID, HF_UPLOAD_ENABLED, mo, training_result):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."
    # Upload is owned by the sequential cell: checkpoint, training result, benchmark progress, final receipt.
    upload_result = {
        "status": "DISABLED"
        if not HF_UPLOAD_ENABLED
        else (
            "PENDING_UPLOAD"
            if training_result["status"] == "PENDING_UPLOAD"
            else ("COMPLETED" if training_result["status"] == "COMPLETED" else "SKIPPED")
        ),
        "repo_id": HF_REPO_ID,
        "models": len(training_result.get("models", [])),
    }
    mo.vstack([mo.md("## 14 · Verified Hub uploads"), mo.ui.table([upload_result], selection=None)])
    return (upload_result,)


@app.cell
def _(
    auth_info,
    EXPERIMENT,
    FAMILY,
    HF_REPO_ID,
    PAIR_OPTIONS,
    RUN_NAME,
    editing_record,
    editing_manifest,
    experiment_spec,
    prepare_editing_records,
    split_editing_records,
):
    assert auth_info["verified"], "Apply a valid HF token before running this cell."

    def test_family_policy_matches_selected_pair():
        spec = experiment_spec(EXPERIMENT)
        assert spec.tie_encoder_decoder_words == (FAMILY == "symmetric")
        assert EXPERIMENT in PAIR_OPTIONS[FAMILY]

    def test_repository_export_uses_public_context_and_rejects_eval():
        raw = {
            "record_type": "repository_patch_v1",
            "role": "train",
            "instance_id": "synthetic-export",
            "source": "bifocalgemma/synthetic-repository-fixture",
            "source_revision": "fixture-v1",
            "group": "fixture/repo",
            "commit": "a" * 40,
            "repos": "fixture/repo",
            "instruction": "Fix helper.",
            "context": "### File: helper.py\nreturn 0\n",
            "target_patch": "diff --git a/helper.py b/helper.py\n",
            "snapshot_sha256": "b" * 64,
            "context_selection": {"gold_used": False},
        }
        assert "pair_hash" not in raw and "instruction_hash" not in raw
        metadata = editing_manifest([raw])[0]
        assert metadata["instance_id"] == raw["instance_id"]
        assert "pair_hash" not in raw and "instruction_hash" not in raw
        row = editing_record(raw, source="editpackft")
        assert metadata["pair_hash"] == row["pair_hash"]
        assert metadata["instruction_hash"] == row["instruction_hash"]
        assert row["context"] == raw["context"]
        try:
            editing_record({**raw, "role": "eval"}, source="editpackft")
            raise AssertionError("Eval export was admitted to training.")
        except ValueError as error:
            assert str(error) == "evaluation_record_cannot_enter_training"

    def test_editing_input_does_not_contain_target_code():
        row = editing_record(
            {
                "old_file": "a.py",
                "new_file": "a.py",
                "old_contents": "x = 0\n",
                "new_contents": "x = 1\n",
                "instruction": "Fix x",
                "commit": "c1",
            },
            source="editpackft",
        )
        assert row["before"] == "x = 0\n"
        assert "+x = 1" in row["target_patch"]
        assert row["instruction"] == "Fix x"

    def test_commit_groups_do_not_overlap():
        rows = []
        for i in range(6):
            rows.append(
                {
                    "old_file": "a.py",
                    "new_file": "a.py",
                    "old_contents": f"x = {i}\n",
                    "new_contents": f"x = {i + 10}\n",
                    "instruction": "Fix x",
                    "commit": f"c{i}",
                }
            )
        records, _ = prepare_editing_records(rows, source="editpackft")
        train, dev = split_editing_records(records, seed=17)
        assert not ({r["group"] for r in train} & {r["group"] for r in dev})

    def test_hub_upload_configuration():
        assert HF_REPO_ID == "daruokta/bifocalgemma-sft"
        path_in_repo = f"{FAMILY}/{EXPERIMENT}/{RUN_NAME}"
        assert path_in_repo.startswith(f"{FAMILY}/")
        assert FAMILY in {"symmetric", "asymmetric", "decoder_only"}

    return


if __name__ == "__main__":
    app.run()
